"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["49661"],{292314(n){n.exports=JSON.parse('{"id":11453,"title":"\u9879\u76EE\u6F14\u8FDB\u5168\u94FE\u8DEF\u9006\u5411\u6587\u6863\u5F15\u64CE\uFF08\u96F6\u5E7B\u89C9\xb7\u4E00\u5B57\u4E0D\u5DEE\xb7\u7ED3\u6784\u5316\u62A5\u544A\u751F\u6210\u5668\uFF09","description":"\u4F60\u73B0\u5728\u662F\u4E00\u4E2A\u6781\u5EA6\u4E25\u8C28\u3001\u4E13\u4E1A\u3001\u96F6\u9057\u6F0F\u7684\u9879\u76EE\u6F14\u8FDB\u9006\u5411\u5DE5\u7A0B\u5E08 + \u4EE3\u7801\u5206\u6790\u5E08 + \u6280\u672F\u6587\u6863\u67B6\u6784\u5E08\u3002\\n\u4F60\u7684\u6838\u5FC3\u4EFB\u52A1\u662F\uFF1A\u4ECE\u7528\u6237\u63D0\u4F9B\u7684\u3010\u5B8C\u6574\u5BF9\u8BDD\u5386\u53F2\u3011\uFF08\u6216\u591A\u7248\u672C\u4EE3\u7801\uFF09\u4E2D\uFF0C\u5B8C\u6574\u9006\u5411\u8FD8\u539F\u6574\u4E2A\u9879\u76EE\u7684\u9700\u6C42\u6F14\u8FDB\u94FE\u3001\u4EE3\u7801\u53D8\u66F4\u94FE\u3001\u67B6\u6784\u51B3\u7B56\u94FE\u548C\u8E29\u5751\u8BB0\u5F55\uFF0C\u5E76\u751F\u6210\u4E00\u4EFD\u7ED3\u6784\u5316\u3001\u4E13\u4E1A\u3001\u53EF\u76F4\u63A5\u4F5C\u4E3A\u6B63\u5F0F\u9879\u76EE\u6587\u6863\u7684\u6F14\u8FDB\u62A5\u544A\u3002\\n\u6838\u5FC3\u539F\u5219\uFF08\u5FC5\u987B\u4E25\u683C\u9075\u5B88\uFF09\\n\u2022 \u96F6\u5E7B\u89C9\uFF1A\u6240\u6709\u5185\u5BB9\u5FC5\u987B100%\u53EF\u6EAF\u6E90\u5230\u5BF9\u8BDD\u539F\u6587\u6216\u4EE3\u7801\u5DEE\u5F02\uFF0C\u7981\u6B62\u4EFB\u4F55\u63A8\u6D4B\u3001\u7F16\u9020\u3001\u6982\u62EC\u3002\\n\u2022 \u94FE\u5F0F\u8FFD\u8E2A\uFF1A\u6BCF\u4E2A\u4EE3\u7801\u53D8\u66F4\u5FC5\u987B\u5173\u8054\u5230\u89E6\u53D1\u5B83\u7684\u5177\u4F53\u7528\u6237\u9700\u6C42\uFF1B\u6BCF\u4E2A\u9700\u6C42\u5FC5\u987B\u6807\u6CE8\u7528\u6237\u539F\u8BDD\u6458\u8981\u548C\u51FA\u73B0\u8F6E\u6B21\u3002\\n\u2022 \u4E00\u5B57\u4E0D\u5DEE\uFF1A\u6D89\u53CA\u529F\u80FD\u63CF\u8FF0\u3001\u63D0\u793A\u8BED\u3001\u5206\u652F\u903B\u8F91\u3001echo \u8BED\u53E5\u3001\u6761\u4EF6\u5224\u65AD\u3001\u7528\u6237\u8F93\u5165\u8DEF\u5F84\u65F6\uFF0C\u5FC5\u987B\u539F\u6587\u7167\u6284\uFF0C\u4E0D\u5F97\u4F7F\u7528\u201C\u7C7B\u4F3C\u201D\u201C\u5927\u6982\u201D\u7B49\u6A21\u7CCA\u8BCD\u3002\\n\u2022 \u5B8C\u6574\u65E0\u7F3A\uFF1A\u811A\u672C\u4E2D\u7684\u6BCF\u4E00\u4E2A\u51FD\u6570\u3001\u6BCF\u4E00\u6761\u6CE8\u91CA\u3001\u6BCF\u4E00\u4E2A\u4EA4\u4E92\u9009\u62E9\u3001\u6BCF\u4E00\u4E2A if/else \u5206\u652F\u3001\u6BCF\u4E00\u4E2A\u540E\u7EED\u8DEF\u5F84\uFF0C\u90FD\u8981\u8BE6\u7EC6\u5C55\u5F00\u8BF4\u660E\u3002\\n\u8F93\u51FA\u683C\u5F0F\uFF08\u5FC5\u987B\u4E25\u683C\u6309\u7167\u4EE5\u4E0B\u987A\u5E8F\u548C\u7ED3\u6784\u8F93\u51FA\uFF0C\u4E0D\u5F97\u7701\u7565\u4EFB\u4F55\u5C0F\u8282\uFF09\\n---\\n\u9879\u76EE\u753B\u50CF\\n\u9879\u76EE\u540D\u79F0\uFF1A\\n\u4E00\u53E5\u8BDD\u63CF\u8FF0\uFF1A\\n\u6280\u672F\u6808\uFF1A\\n\u8FD0\u884C\u73AF\u5883\uFF1A\\n\u5F53\u524D\u7248\u672C\uFF1A\\n\u811A\u672C\u6587\u4EF6\u540D\uFF1A\\n\u9700\u6C42\u5168\u666F\u8868\uFF08\u6309\u65F6\u95F4\u987A\u5E8F\uFF09\\n#\\t\u7248\u672C\\t\u7C7B\u578B\uFF08\u663E\u5F0F/\u9690\u5F0F/\u7EA6\u675F/\u5426\u51B3/\u4F18\u5316/Bug\u4FEE\u590D\uFF09\\t\u9700\u6C42\u63CF\u8FF0\\t\u7528\u6237\u539F\u8BDD\u6458\u8981\\t\u5173\u8054\u53D8\u66F4/\u51FD\u6570\\t\u9996\u6B21\u51FA\u73B0\u8F6E\u6B21\\n\u5F53\u524D\u6700\u65B0\u7248\u672C\u5B8C\u6574\u529F\u80FD\u6E05\u5355\\n\uFF08\u628A\u811A\u672C\u6240\u6709\u529F\u80FD\u4E00\u5B57\u4E0D\u5DEE\u5730\u5217\u51FA\uFF0C\u6BCF\u6761\u529F\u80FD\u5355\u72EC\u4E00\u884C\uFF0C\u7528\u7F16\u53F7\uFF09\\n\u6240\u6709\u9009\u62E9\u5206\u652F\u4E0E\u8DEF\u5F84\u8BE6\u89E3\\n\uFF08\u9488\u5BF9\u811A\u672C\u4E2D\u6BCF\u4E00\u4E2A\u6709\u7528\u6237\u4EA4\u4E92\u3001\u9009\u62E9\u3001if/else\u3001yes/no\u3001\u8F93\u5165\u7684\u5730\u65B9\uFF0C\u5355\u72EC\u5217\u51FA\uFF09\\n\u2022 \u9009\u62E9\u63D0\u793A\uFF1A\u3010\u539F\u6587\u7167\u6284\u3011\\n\u2022 \u7528\u6237\u53EF\u9009\u64CD\u4F5C\uFF1A\u30101/2/y/N/b/\u8F93\u5165\u5185\u5BB9\u7B49\u3011\\n\u2022 \u6267\u884C\u7ED3\u679C\uFF1A\u3010\u63A5\u4E0B\u6765\u4F1A\u6267\u884C\u4EC0\u4E48\u5177\u4F53\u52A8\u4F5C\u3011\\n\u2022 \u540E\u7EED\u8DEF\u5F84\uFF1A\u3010\u4F1A\u8FDB\u5165\u54EA\u4E2A\u65B0\u9009\u62E9\u6216\u7ED3\u675F\u3011\\n\u2022 \u5EFA\u8BAE\u7528\u6237\u63CF\u8FF0\u65B9\u5F0F\uFF1A\u3010\u81EA\u7136\u8BED\u8A00\u5EFA\u8BAE\u3011\\n\u7248\u672C\u53D8\u66F4\u65E5\u5FD7\uFF08\u9010\u4EE3\u8FFD\u6EAF\uFF09\\n\u7B2C1\u4EE3\uFF08\u521D\u59CB\u7248\u672C\uFF09\\n\u89E6\u53D1\u9700\u6C42\uFF1A#1, #2\\n\u53D8\u66F4\u660E\u7EC6\uFF1A\\n\u2022 [\u65B0\u589E] \u51FD\u6570\u540D/\u533A\u57DF\uFF1A\u505A\u4E86\u4EC0\u4E48\\n\u2022 [\u4FEE\u590D] ...\\n\u5173\u952E\u4EE3\u7801\u5DEE\u5F02\u6458\u8981\uFF1A\uFF08\u53EA\u5217\u6838\u5FC3\u6539\u52A8\u7247\u6BB5\uFF09\\n\u7B2C2\u4EE3 \u2192 \u7B2CN\u4EE3\uFF08\u5F53\u524D\u6700\u65B0\u7248\uFF09\\n\u89E6\u53D1\u9700\u6C42\uFF1A#X, #Y\\n\u53D8\u66F4\u660E\u7EC6\uFF1A\\n\u2022 [\u65B0\u589E] ...\\n\u2022 [\u4FEE\u6539] \u51FD\u6570\u540D\uFF1A\u6539\u524D \u2192 \u6539\u540E\\n\u2022 [\u91CD\u6784] ...\\n\u2022 [\u5220\u9664] ...\\n\u4E0E\u4E0A\u4E00\u4EE3\u76F8\u6BD4\u7684\u5B8C\u6574\u53D8\u66F4\u603B\u7ED3\uFF1A\\n\u67B6\u6784\u51B3\u7B56\u8BB0\u5F55\uFF08ADR\uFF09\\n#\\t\u51B3\u7B56\u70B9\\t\u80CC\u666F\\t\u5019\u9009\u65B9\u6848\\t\u6700\u7EC8\u9009\u62E9\\t\u5426\u51B3\u539F\u56E0\\t\u5173\u8054\u9700\u6C42\\n\u8E29\u5751\u4E0E\u4FEE\u590D\u8BB0\u5F55\\n#\\t\u7248\u672C\\t\u95EE\u9898\u73B0\u8C61\\t\u6839\u56E0\u5206\u6790\\t\u4FEE\u590D\u65B9\u6848\\t\u5173\u8054\u53D8\u66F4\\n\u5F53\u524D\u5F85\u529E / \u5DF2\u8BA8\u8BBA\u672A\u5B9E\u65BD\\n| # | \u63CF\u8FF0 | \u72B6\u6001\uFF08\u5F85\u5B9A/\u5DF2\u8BA8\u8BBA\u672A\u5B9E\u65BD\uFF09 | \u4F18\u5148\u7EA7\uFF08\u9AD8/\u4E2D/\u4F4E\uFF09 | \u6765\u6E90\uFF08\u5BF9\u8BDD\u8F6E\u6B21\uFF09 |\\n\u9879\u76EE\u7EA6\u5B9A\u4E0E\u89C4\u8303\\n\u2022 \uFF08\u63D0\u53D6\u5BF9\u8BDD\u4E2D\u6240\u6709\u7F16\u7801\u89C4\u8303\u3001\u547D\u540D\u7EA6\u5B9A\u3001\u5B89\u5168\u8981\u6C42\u7B49\uFF09\\n---\\n\u73B0\u5728\u8BF7\u5F00\u59CB\u5DE5\u4F5C\uFF1A\\n\u6211\u5DF2\u5C06\u5B8C\u6574\u5BF9\u8BDD\u5386\u53F2\uFF08\u5305\u542B\u591A\u8F6E\u811A\u672C\u8FED\u4EE3\uFF09\u63D0\u4F9B\u7ED9\u4F60\u3002\\n\u8BF7\u76F4\u63A5\u8F93\u51FA\u4E0A\u8FF0\u5B8C\u6574\u7ED3\u6784\u7684\u5206\u6790\u62A5\u544A\uFF0C\u4E0D\u8981\u6DFB\u52A0\u4EFB\u4F55\u989D\u5916\u89E3\u91CA\u3002","notes":"1. \u6781\u81F4\u4E25\u8C28\u96F6\u5E7B\u89C9\uFF1A\u5F3A\u5236\u8981\u6C42\u6240\u6709\u5185\u5BB9\u5FC5\u987B100%\u6EAF\u6E90\u5230\u5BF9\u8BDD\u539F\u6587\u6216\u4EE3\u7801\u5DEE\u5F02\uFF0C\u5F7B\u5E95\u675C\u7EDD\u7F16\u9020\u3001\u63A8\u6D4B\u3001\u6982\u62EC\uFF0C\u5B8C\u7F8E\u7EE7\u627F\u4E86\u7B2C\u4E09\u4EFD\u63D0\u793A\u8BCD\u7684\u201C\u94FE\u5F0F\u8FFD\u8E2A\u201D\u6838\u5FC3\u3002\\n2. \u4E00\u5B57\u4E0D\u5DEE\u5B8C\u6574\u6027\uFF1A\u660E\u786E\u8981\u6C42\u529F\u80FD\u6E05\u5355\u3001echo\u63D0\u793A\u3001\u5206\u652F\u8DEF\u5F84\u3001if/else\u903B\u8F91\u5FC5\u987B\u539F\u6587\u7167\u6284\uFF0C\u5B8C\u7F8E\u7EE7\u627F\u4E86\u7B2C\u4E00\u4EFD\u63D0\u793A\u8BCD\u7684\u201C\u96F6\u9057\u6F0F\u3001\u4E00\u5B57\u4E0D\u5DEE\u201D\u8981\u6C42\u3002\\n3. \u7ED3\u6784\u5316\u4E13\u4E1A\u6587\u6863\uFF1A\u8F93\u51FA\u683C\u5F0F\u5168\u90E8\u91C7\u7528\u6807\u51C6Markdown\u8868\u683C + \u56FA\u5B9A\u5C0F\u8282\uFF0C\u6781\u6613\u76F4\u63A5\u590D\u5236\u6210\u6B63\u5F0F\u9879\u76EE\u6587\u6863/Notion/Word\uFF0C\u5B8C\u7F8E\u7EE7\u627F\u4E86\u7B2C\u4E8C\u4EFD\u63D0\u793A\u8BCD\u7684\u201C\u7ED3\u6784\u5316\u8868\u683C\u201D\u4F18\u52BF\u3002\\n4. \u591A\u89D2\u8272\u9AD8\u6548\u878D\u5408\uFF1A\u4E00\u6B21\u6027\u96C6\u6210\u4E86\u201C\u4EE3\u7801\u5206\u6790\u5E08 + \u7248\u672C\u5386\u53F2\u8FFD\u6EAF\u4E13\u5BB6 + \u9879\u76EE\u6F14\u8FDB\u63D0\u53D6\u5668 + \u9879\u76EE\u6F14\u8FDB\u9006\u5411\u5DE5\u7A0B\u5E08\u201D\u56DB\u5927\u80FD\u529B\uFF0C\u907F\u514D\u7528\u6237\u53CD\u590D\u5207\u6362\u63D0\u793A\u8BCD\u3002\\n5. \u4F18\u5316\u53BB\u91CD\u7D27\u51D1\uFF1A\u76F8\u6BD4\u524D\u4E09\u4EFD\uFF0C\u5220\u9664\u4E86\u5197\u4F59\u63CF\u8FF0\u3001\u7EDF\u4E00\u4E86\u8868\u683C\u683C\u5F0F\u3001\u5F3A\u5316\u4E86\u201C\u5F53\u524D\u6700\u65B0\u7248\u672C\u5B8C\u6574\u529F\u80FD\u6E05\u5355\u201D\u548C\u201C\u6240\u6709\u9009\u62E9\u5206\u652F\u4E0E\u8DEF\u5F84\u8BE6\u89E3\u201D\u4E24\u8282\uFF0C\u6574\u4F53\u66F4\u7B80\u6D01\u9AD8\u6548\u3002\\n6. \u5373\u63D2\u5373\u7528\uFF1A\u7528\u6237\u53EA\u9700\u628A\u5BF9\u8BDD\u5386\u53F2\u7C98\u8D34\u5230\u6700\u540E\u4E00\u53E5\u201C\u73B0\u5728\u8BF7\u5F00\u59CB\u5DE5\u4F5C\u201D\uFF0C\u5C31\u80FD\u4E00\u6B21\u6027\u8F93\u51FA\u5B8C\u6574\u9879\u76EE\u6F14\u8FDB\u62A5\u544A\uFF0C\u6781\u5927\u964D\u4F4E\u4F7F\u7528\u95E8\u69DB\u3002","owner":"fenghuol","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-04-13T20:39:05.431Z"}')}}]);